    factsAdvanced: { de: ["Hauptstraße im östlichen Monaco", "Verbindung zum Stadtteil La Rousse", "Geprägt durch Hochhausbebauung", "Wichtiger Knotenpunkt im Verkehrsnetz", "Symbol für die städtebauliche Dichte", "Hohe Wohnattraktivität im Osten", "Zentraler Bestandteil des östlichen Stadtgebiets"], hu: [], ro: [], en: ["Features an iconic location in Monaco", "Integral to the local infrastructure", "Reflects the principality's architectural heritage", "Attracts international interest and prestige", "Strategically situated in a high-value district", "Showcases modern urban planning integrated with history", "Offers unique insights into Monégasque society"] }
